const axios = require('axios');

// Whitelist of allowed domains for outgoing requests
const ALLOWED_DOMAINS = ['api.externalservice.com', 'data.provider.org'];

function isValidOutboundUrl(url) {
  try {
    const parsed = new URL(url);
    return ALLOWED_DOMAINS.includes(parsed.hostname);
  } catch (e) {
    return false;
  }
}

